messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Three.js Red vs Blue Race</title>
  <style>
    body { margin: 0; overflow: hidden; background: #87CEEB; }
    canvas { display: block; }
    #info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      font-family: Arial, Helvetica, sans-serif;
      font-size: 18px;
      background: rgba(0,0,0,0.5);
      padding: 8px 16px;
      border-radius: 8px;
      pointer-events: none;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="info">🏁 RED vs BLUE — red overtakes mid-race!</div>
  <script type="module">
    import * as THREE from './three.module.js';

    // --- Scene setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    // --- Camera ---
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 8, 14);
    camera.lookAt(0, 1, 0);

    // --- Renderer ---
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lights ---
    const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    scene.add(dirLight);

    const backLight = new THREE.DirectionalLight(0xffffff, 0.5);
    backLight.position.set(-5, 5, -5);
    scene.add(backLight);

    // --- Ground ---
    const groundGeo = new THREE.PlaneGeometry(30, 20);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x4caf50, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.2;
    ground.receiveShadow = true;
    scene.add(ground);

    // --- Road / track ---
    const roadGeo = new THREE.PlaneGeometry(6, 30);
    const roadMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.9 });
    const road = new THREE.Mesh(roadGeo, roadMat);
    road.rotation.x = -Math.PI / 2;
    road.position.y = -0.1;
    road.position.z = 0;
    road.receiveShadow = true;
    scene.add(road);

    // Road markings (dashed center line)
    const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    for (let i = -10; i <= 10; i += 2) {
      const dashGeo = new THREE.BoxGeometry(0.2, 0.05, 0.8);
      const dash = new THREE.Mesh(dashGeo, lineMat);
      dash.position.set(0, -0.05, i);
      dash.rotation.x = -Math.PI / 2;
      scene.add(dash);
    }

    // --- Finish line (checkered pattern simplified) ---
    const finishGroup = new THREE.Group();
    const finishMatWhite = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 });
    const finishMatBlack = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4 });
    const tileSize = 0.5;
    const tileDepth = 0.1;
    const numTiles = 8;
    const startX = -2.0;
    for (let i = 0; i < numTiles; i++) {
      const x = startX + i * tileSize;
      const mat = (i % 2 === 0) ? finishMatWhite : finishMatBlack;
      const tile = new THREE.Mesh(new THREE.BoxGeometry(tileSize, 0.05, tileDepth), mat);
      tile.position.set(x, 0.05, -10.5);
      finishGroup.add(tile);
    }
    // white line across road
    const lineGeo = new THREE.BoxGeometry(4.5, 0.1, 0.2);
    const lineMatFinish = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const finishLine = new THREE.Mesh(lineGeo, lineMatFinish);
    finishLine.position.set(0, 0.1, -10.5);
    finishGroup.add(finishLine);
    scene.add(finishGroup);

    // --- Car factory ---
    function createCar(color) {
      const carGroup = new THREE.Group();

      // Body
      const bodyGeo = new THREE.BoxGeometry(1.2, 0.6, 2.2);
      const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.2 });
      const body = new THREE.Mesh(bodyGeo, bodyMat);
      body.position.y = 0.4;
      body.castShadow = true;
      carGroup.add(body);

      // Cabin
      const cabinGeo = new THREE.BoxGeometry(0.9, 0.5, 1.0);
      const cabinMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
      const cabin = new THREE.Mesh(cabinGeo, cabinMat);
      cabin.position.set(0, 0.8, 0.2);
      cabin.castShadow = true;
      carGroup.add(cabin);

      // Wheels
      const wheelGeo = new THREE.CylinderGeometry(0.25, 0.25, 0.2, 16);
      const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9 });
      const wheelPositions = [
        [-0.7, 0.25, -0.8],
        [0.7, 0.25, -0.8],
        [-0.7, 0.25, 0.8],
        [0.7, 0.25, 0.8]
      ];
      wheelPositions.forEach(pos => {
        const wheel = new THREE.Mesh(wheelGeo, wheelMat);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        wheel.castShadow = true;
        carGroup.add(wheel);
      });

      // Headlights (small glow)
      const headlightMat = new THREE.MeshStandardMaterial({ color: 0xffffaa, emissive: 0xffffaa });
      const headlightGeo = new THREE.SphereGeometry(0.12, 8, 8);
      const hl1 = new THREE.Mesh(headlightGeo, headlightMat);
      hl1.position.set(-0.4, 0.4, 1.1);
      carGroup.add(hl1);
      const hl2 = new THREE.Mesh(headlightGeo, headlightMat);
      hl2.position.set(0.4, 0.4, 1.1);
      carGroup.add(hl2);

      // Tail lights (red)
      const tailMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0x330000 });
      const tailGeo = new THREE.SphereGeometry(0.1, 8, 8);
      const tl1 = new THREE.Mesh(tailGeo, tailMat);
      tl1.position.set(-0.4, 0.4, -1.1);
      carGroup.add(tl1);
      const tl2 = new THREE.Mesh(tailGeo, tailMat);
      tl2.position.set(0.4, 0.4, -1.1);
      carGroup.add(tl2);

      return carGroup;
    }

    // --- Create cars ---
    const redCar = createCar(0xff0000);
    redCar.position.set(-0.8, 0, 8); // start behind
    redCar.rotation.y = Math.PI; // face +Z direction (toward finish at -10)
    scene.add(redCar);

    const blueCar = createCar(0x0044ff);
    blueCar.position.set(0.8, 0, 6); // blue starts ahead
    blueCar.rotation.y = Math.PI;
    scene.add(blueCar);

    // --- Animation state ---
    const trackLength = 18; // from z=8 to z=-10
    const finishZ = -10.5;
    const startZ = 8;

    let blueZ = 6;      // blue starts ahead
    let redZ = 8;       // red starts behind
    let raceTime = 0;
    const raceDuration = 5.0; // seconds per loop

    // --- Animation loop ---
    const clock = new THREE.Clock();

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      raceTime += delta;

      // Race progress (0 to 1)
      let t = raceTime / raceDuration;
      if (t >= 1.0) {
        raceTime = 0.0;
        t = 0.0;
        // reset positions
        blueZ = 6;
        redZ = 8;
      }

      // Blue car: starts fast, slows slightly (linear-ish)
      const blueProgress = Math.min(t * 1.0, 1.0); // blue reaches finish at t=1
      // Red car: slower at first, then accelerates to overtake mid-race
      let redProgress;
      if (t < 0.45) {
        // red is slower early
        const localT = t / 0.45;
        redProgress = localT * 0.35; // reaches 0.35 at t=0.45
      } else {
        // red accelerates and overtakes
        const localT = (t - 0.45) / 0.55;
        redProgress = 0.35 + localT * 0.65; // reaches 1.0 at t=1.0
      }
      // clamp
      redProgress = Math.min(redProgress, 1.0);

      // Convert progress to z position
      // startZ = 8, finishZ = -10.5, trackLength = 18.5
      const blueZpos = startZ - blueProgress * trackLength;
      const redZpos = startZ - redProgress * trackLength;

      // Update car positions
      blueCar.position.z = blueZpos;
      redCar.position.z = redZpos;

      // Slight bounce for wheels (fake rolling)
      const wheelBounce = Math.sin(raceTime * 15) * 0.05;
      redCar.children.forEach((child, idx) => {
        if (idx >= 3 && idx <= 6) { // wheels are indices 3-6 (after body, cabin)
          child.position.y = 0.25 + wheelBounce;
        }
      });
      blueCar.children.forEach((child, idx) => {
        if (idx >= 3 && idx <= 6) {
          child.position.y = 0.25 + Math.sin(raceTime * 15 + 0.5) * 0.05;
        }
      });

      // Camera follows race: keep both cars in view
      const midZ = (blueZpos + redZpos) / 2;
      camera.position.set(0, 8, midZ + 10);
      camera.lookAt(0, 1, midZ - 2);

      // Render
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    // --- Resize handler ---
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

  </script>
</body>
</html>
```
